local _map = {}
local _alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
for k=1,#_alphabet do _map[_alphabet:byte(k)] = k-1 end
local _encrypted = {}
local _acc, _bits, _index = 0, 0, 0
for _char in _payload:gmatch('.') do
    local _ascii = _char:byte()
    local _value = _map[_ascii]
    if _value then
        _acc = _acc * 64 + _value
        _bits = _bits + 6
        if _bits >= 8 then
            _bits = _bits - 8
            local _unit = math.floor(_acc / 2 ^ _bits) % 256
            _acc = _acc % (2 ^ _bits)
            _index = _index + 1
            _encrypted[_index] = (_unit - ((_index * 53 + math.floor(_index / 7) * 17 + 131) % 256)) % 256
        end
    end
end
_payload = nil
local _source, _n, _pos, _buffer = {}, 0, 1, _encrypted
while _pos <= #_buffer do
    local _flags = _buffer[_pos]
    _pos = _pos + 1
    for _bit=0,7 do
        if _pos > #_buffer then break end
        if math.floor(_flags / (2 ^ _bit)) % 2 == 1 then
            local _offset = _buffer[_pos] + _buffer[_pos+1] * 256
            local _count = _buffer[_pos+2] + 3
            _pos = _pos + 3
            assert(_offset > 0 and _offset <= _n, 'Неверный блок данных')
            for _k=1,_count do
                _n = _n + 1
                _source[_n] = _source[_n-_offset]
            end
        else
            _n = _n + 1
            _source[_n] = _buffer[_pos]
            _pos = _pos + 1
        end
    end
end
_buffer = nil
local _slices = {}
for _p=1,_n,1024 do
    local _slice = {}
    for _q=_p,math.min(_p+1023,_n) do
        _slice[#_slice+1] = string.char(_source[_q])
    end
    _slices[#_slices+1] = table.concat(_slice)
end
_source = nil
local _code = table.concat(_slices)
_slices = nil
local _chunk, _error = loadstring(_code, '@Shishan.lua')
if not _chunk then error('[Помощник онлайн] '..tostring(_error)) end
